Certainly! Below is a simple Python script using the Flask framework to create a web form that accepts and saves user-inputted text.

### Prerequisites:
- Install Flask: `pip install flask`
- Install Flask-SQLAlchemy for database operations: `pip install flask_sqlalchemy`

### Script:

```python
from flask import Flask, render_template, request, redirect, url_for
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] ='sqlite:///users.db'
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True))
    name = db.Column(db.String(100)), nullable=False)
    text = db.Column(db.Text), nullable=False)

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/submit', methods=['POST'])
def submit():
    name = request.form.get('name')
    text = request.form.get('text')

    if not name or not text:
        return "Please fill in all fields."

    new_user = User(name=name, text=text)
    db.session.add(new_user)
    db.session.commit()

    return redirect(url_for('index')))

if __name__ == '__main__':
    app
